using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ThisisFineAchievementData", menuName = "Data/Achievements/ThisisFineAchievementData")]
public class ThisisFineAchievementData : AchievementData
{
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private CurrentCompanions currentCompanions;

	protected override bool UnlockCustomRequirementCheck()
	{
		ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
		int num = base.AchievementSecondVariableAmount;
		int num2 = 0;
		num2 += currentCorruptedAnimals.GetEnemiesWithAtLeastXAfflictionAmount(num);
		if (ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().IsAfflictionActiveGetAmount() >= num)
		{
			num2++;
		}
		num2 += currentCompanions.GetCompanionsWithAtLeastXAfflictionAmount(num);
		if (num2 >= base.AchievementVariableAmount)
		{
			return true;
		}
		return false;
	}
}
